def chunk(doc,index): return next(c for c in chunks if c['metadatos']['parent_id']==doc and c['metadatos']['chunk_index']==index)
items=[]
def add(id,category,q,groups,reuse=None,escape=None):
    facts=[]
    for doc,index,claims in groups:
        c=chunk(doc,index)
        for claim in claims:
            facts.append(dict(hecho=claim,document_id=doc,chunk_id=c['id'],fragmento=c['documento']))
    items.append(dict(id=id,categoria=category,pregunta=q,respuesta_esperada=' '.join(f['hecho'] for f in facts) if not escape else 'No poseo información suficiente en la base de conocimiento para responder esa consulta.',hechos_obligatorios=facts if not escape else [dict(hecho='Reconocer la falta de información suficiente y no inventar '+('requisitos fitosanitarios.' if id=='E1' else 'un precio u honorario.'))],document_ids=sorted({f['document_id'] for f in facts}),chunk_ids=sorted({f['chunk_id'] for f in facts}),espera_escape=bool(escape),justificacion_escape=escape or 'La intención tiene respaldo explícito en el corpus efectivo.',reutilizacion_b=reuse or dict(exacta=False,relacionada=False,evidencia=[],nota='No se identificó uso en los archivos de desarrollo revisados; no prueba independencia absoluta.')))
